export const BW2_WORK_ALIASES: readonly Bw2WorkAlias[] = DEFINITIONS.map(([id, name, scope, description]) => ({ id, name, scope, description }));
const byId = new Map(BW2_WORK_ALIASES.map((work) => [work.id, work]));

export function bw2WorkAlias(id: number): Bw2WorkAlias {
  return byId.get(id) ?? { id, name: `work_${id.toString(16)}`, scope: "unknown", description: "Unidentified work ID. Its runtime storage and event meaning have not been documented; no event name is inferred." };
}

